script:
const el=root_element;
frappe.call({method:"frappe.client.get_count",args:{doctype:"EE Lead",filters:{status:["not in",["Lost"]]}},callback(r){const n=el.querySelector("#ee-h-leads .ee-h-num");if(n)n.textContent=(r.message||0).toLocaleString();}});
frappe.call({method:"frappe.client.get_count",args:{doctype:"EE Student",filters:{status:["not in",["Dropped"]]}},callback(r){const n=el.querySelector("#ee-h-students .ee-h-num");if(n)n.textContent=(r.message||0).toLocaleString();}});
frappe.call({method:"frappe.client.get_list",args:{doctype:"EE Nomod Payment Link",filters:{status:"Paid"},fields:["sum(amount) as total"],limit_page_length:1},callback(r){const n=el.querySelector("#ee-h-collected .ee-h-num");if(n){const v=r.message&&r.message[0]&&r.message[0].total;n.textContent=v?"AED "+Number(v).toLocaleString():"AED 0";}}});
function tick(){const now=new Date();const d=el.querySelector("#ee-h-date");const t=el.querySelector("#ee-h-time");if(d)d.textContent=now.toLocaleDateString("en-GB",{weekday:"long",day:"numeric",month:"short",year:"numeric"});if(t)t.textContent=now.toLocaleTimeString("en-GB",{hour:"2-digit",minute:"2-digit",second:"2-digit"});}tick();setInterval(tick,1000);
el.querySelectorAll(".ee-clickable").forEach(function(card){card.addEventListener("click",function(){var r=card.getAttribute("data-route");if(r)window.location.href="/app/"+r;});});

const container = root_element.querySelector(".ee-leads-source");
const chartAsset = "/assets/frappe/node_modules/frappe-charts/dist/frappe-charts.min.iife.js";
frappe.require(chartAsset, function() {
    frappe.call({
        method: "expertedge.api.dashboard.get_leads_by_source",
        callback: function(r) {
            if (!r.message || !r.message.length) {
                container.innerHTML = '<p style="color:var(--text-muted);">No leads yet</p>';
                return;
            }
            var labels = r.message.map(function(d) { return d.label; });
            var values = r.message.map(function(d) { return d.value; });
            container.innerHTML = '<div class="ee-chart-title ee-clickable">Leads by Source <span style="font-size:11px;color:var(--text-muted);">→ View All</span></div><div class="ee-chart-container"></div>';
            container.querySelector(".ee-chart-title").addEventListener("click", function() { window.location.href = "/app/ee-lead"; });
            var chartDiv = container.querySelector(".ee-chart-container");
            new frappe.Chart(chartDiv, {
                data: { labels: labels, datasets: [{ values: values }] },
                type: "pie",
                height: 280,
                colors: ["#e91e63", "#2196f3", "#0077b5", "#ff9800", "#4caf50"]
            });
        }
    });
});

style:
.ee-leads-source { background: var(--card-bg); border-radius: 8px; padding: 16px; }
.ee-chart-title { font-size: 14px; font-weight: 600; color: var(--heading-color); margin-bottom: 12px; }
