script:
const container = root_element.querySelector(".ee-enrollments");
frappe.call({
    method: "expertedge.api.dashboard.get_enrollments_by_batch",
    callback: function(r) {
        if (!r.message || !r.message.length) {
            container.innerHTML = '<p style="color:var(--text-muted);">No enrollments yet</p>';
            return;
        }
        var html = '<div class="ee-chart-title">Enrollments by Batch</div>';
        var max = Math.max.apply(null, r.message.map(function(d) { return d.count; })) || 1;
        r.message.forEach(function(d) {
            var pct = Math.min((d.count / max) * 100, 100);
            html += '<div class="ee-bar-row" data-batch="' + frappe.utils.escape_html(d.batch) + '">' +
                '<div class="ee-bar-label">' + frappe.utils.escape_html(d.batch) + '</div>' +
                '<div class="ee-bar-wrap">' +
                '<div class="ee-bar-track"><div class="ee-bar-fill" style="width:' + pct + '%"></div></div>' +
                '<div class="ee-bar-val">' + d.count + '</div>' +
                '</div></div>';
        });
        container.innerHTML = html;
        container.querySelectorAll(".ee-bar-row").forEach(function(row) {
            row.addEventListener("click", function() {
                var batch = row.getAttribute("data-batch");
                window.location.href = "/app/ee-student?batch=" + encodeURIComponent(batch);
            });
        });
    }
});

style:
.ee-enrollments { background: var(--card-bg); border-radius: 8px; padding: 16px; }
.ee-chart-title { font-size: 14px; font-weight: 600; color: var(--heading-color); margin-bottom: 12px; }
.ee-bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; cursor: pointer; padding: 4px; border-radius: 4px; transition: background 0.15s; }
.ee-bar-row:hover { background: var(--control-bg); }
.ee-bar-label { width: 180px; font-size: 13px; color: var(--text-color); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ee-bar-wrap { flex: 1; display: flex; align-items: center; gap: 8px; }
.ee-bar-track { flex: 1; height: 20px; background: var(--control-bg); border-radius: 4px; overflow: hidden; }
.ee-bar-fill { height: 100%; background: var(--primary); border-radius: 4px; transition: width 0.3s; }
.ee-bar-val { font-size: 13px; font-weight: 600; min-width: 30px; text-align: right; }

script:
const container = root_element.querySelector(".ee-stats-grid");
frappe.call({
    method: "expertedge.api.dashboard.get_dashboard_stats",
    callback: function(r) {
        if (!r.message) { container.innerHTML = "<p>No data</p>"; return; }
        var d = r.message;
        var cards = [
            { label: "New Leads Today", value: d.new_leads_today, color: "var(--red-500)", route: "/app/ee-lead?status=New" },
            { label: "Calls Today", value: d.calls_today, color: "var(--primary)", route: "/app/query-report/Call Activity" },
            { label: "In Counselling", value: d.leads_in_counselling, color: "var(--orange-500)", route: "/app/ee-lead?status=Counselling+Scheduled" },
            { label: "Pre-Approval Pending", value: d.pending_pre_approval, color: "var(--yellow-500)", route: "/app/ee-student?status=Pre-Approval+Pending" },
            { label: "Balance Pending", value: d.pending_balance, color: "var(--red-500)", route: "/app/ee-student?status=Balance+Pending" },
            { label: "Enrolled (Month)", value: d.enrolled_this_month, color: "var(--green-500)", route: "/app/ee-student?status=Enrolled" }
        ];
        var html = "";
        cards.forEach(function(c) {
            html += '<div class="ee-stat-card" data-route="' + c.route + '">' +
                '<div class="ee-stat-value" style="color:' + c.color + ';">' + c.value + '</div>' +
                '<div class="ee-stat-label">' + c.label + '</div>' +
                '</div>';
        });
        container.innerHTML = html;
        container.querySelectorAll(".ee-stat-card").forEach(function(card) {
            card.addEventListener("click", function() {
                window.location.href = card.getAttribute("data-route");
            });
        });
    }
});

style:
.ee-stats-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 12px; }
@media (max-width: 1200px) { .ee-stats-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 576px) { .ee-stats-grid { grid-template-columns: repeat(2, 1fr); } }
.ee-stat-card { background: var(--card-bg); border-radius: 8px; padding: 16px; text-align: center; border: 1px solid var(--border-color); cursor: pointer; transition: all 0.15s; }
.ee-stat-card:hover { border-color: var(--primary); box-shadow: 0 2px 8px rgba(0,0,0,0.08); }
.ee-stat-value { font-size: 28px; font-weight: 700; line-height: 1.2; }
.ee-stat-label { font-size: 12px; color: var(--text-muted); margin-top: 4px; }
